#include "ksLoaderCodecTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::LoaderCodecTask;using S=T::Stage;
void check(bool v){if(!v)throw std::runtime_error("LoaderCodec logical policy differs");}
int main(){try{uint64_t cases=0,intervals=0;for(unsigned low=0;low<128;++low)for(unsigned high=0;high<128;++high){T t(T::Kind::Word);unsigned child=0;auto read=[](T::Read,uint32_t){return 0u;};auto write=[](T::Write,uint32_t,uint16_t){};while(!t.complete()){auto s=t.stage();unsigned cost=t.nextClocks();check(cost&&!t.advanceBefore(cost-1,read,write)&&s==t.stage());check(t.advanceBefore(cost,read,write)==cost);++intervals;if(t.awaitingChild())t.resumeChild(child++?high:low,0,0,0);}check(t.word()==(high*128+low));++cases;}
for(uint32_t seed=0;seed<65536;++seed){const uint32_t value=seed*0x9e3779b9u;T t(T::Kind::Long);unsigned child=0;auto read=[](T::Read,uint32_t){return 0u;};auto write=[](T::Write,uint32_t,uint16_t){};while(!t.complete()){auto cost=t.nextClocks();check(cost&&t.advanceBefore(cost,read,write)==cost);++intervals;if(t.awaitingChild()){const auto s=t.resumeStage();t.resumeChild(s==S::BindTopWeight?uint8_t(value>>28):0,child++?((value>>14)&0x3fff):(value&0x3fff),0,0);}}check(t.payload()==value);++cases;}
for(unsigned seed=0;seed<4096;++seed){T t(T::Kind::Group,0,0x30001,0xfffffff0u);unsigned child=0,writes=0;uint32_t expected=0xfffffff0u;auto read=[](T::Read,uint32_t){return 0u;};auto write=[&](T::Write,uint32_t at,uint16_t v){check(at==0x30001+writes*2);expected+=v;++writes;};while(!t.complete()){auto cost=t.nextClocks();check(cost&&t.advanceBefore(cost,read,write)==cost);++intervals;if(t.awaitingChild())t.resumeChild(0,((seed*73+child++*31)&0x3fff),0,0);}check(writes==7&&t.sum()==expected&&t.destination()==0x3000f);++cases;}
std::cout<<"PASS: "<<cases<<" LoaderCodec policies / "<<intervals<<" intervals; logical math/routes/deferred writes and insufficient budgets\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
